const fs = require('fs');
const ExcelJS = require('c:/Users/lg/resilient-bardeen/node_modules/exceljs');

async function fixTargetExcel() {
  const filePath = 'C:/Users/lg/Desktop/오늘/(데이터검증팀)실사 DB 취합_전달용_260720_검증앤새로입력.xlsx';
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보') || workbook.worksheets[0];

  let cleared = 0;
  for (let r = 11847; r <= 12346; r++) {
    const row = sheet.getRow(r);
    const bizCell = row.getCell(4).value;
    const bizno = (bizCell ? (typeof bizCell === 'object' && bizCell.text ? bizCell.text : String(bizCell)) : '').replace(/[^0-9]/g, '');

    if (bizno.length === 10) {
      const middle = parseInt(bizno.substring(3, 5), 10);
      const isPersonal = middle >= 1 && middle <= 79;

      if (isPersonal) {
        if (row.getCell(25).value) {
          console.log('Clearing Row ' + r + ' (' + row.getCell(3).value + '): ' + row.getCell(25).value);
          row.getCell(25).value = null;
          row.getCell(25).fill = null;
          cleared++;
        }
        if (row.getCell(31).value) {
          row.getCell(31).value = null;
          row.getCell(31).fill = null;
        }
        row.commit();
      }
    }
  }

  console.log('Total cleared personal corp numbers in file:', cleared);
  const tempPath = filePath + '.tmp';
  await workbook.xlsx.writeFile(tempPath);
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  fs.renameSync(tempPath, filePath);
  console.log('Successfully updated:', filePath);

  // also sync to repo data folder
  const repoPath = 'c:/Users/lg/resilient-bardeen/data/(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  fs.copyFileSync(filePath, repoPath);
  console.log('Synced to repo.');
}

fixTargetExcel().catch(console.error);
